"""Concatenate every spec file into SPEC_BUNDLE.md (for uploading to claude.ai chat).

Usage:  python tools/bundle_spec.py
SPEC_BUNDLE.md is generated — edit the files in spec/ and re-run this script instead of editing it.
"""

from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SPEC_DIR = ROOT / "spec"
OUT = ROOT / "SPEC_BUNDLE.md"


def main() -> None:
    parts = [
        "<!-- GENERATED by tools/bundle_spec.py from spec/*.md — do not edit by hand. -->\n",
        "# ETAutomationsAPI — complete specification bundle\n",
        "Files are concatenated in reading order; each starts with a `FILE:` marker.\n",
    ]
    for path in sorted(SPEC_DIR.glob("*.md")):
        rel = path.relative_to(ROOT).as_posix()
        text = path.read_text(encoding="utf-8").rstrip() + "\n"
        parts.append(f"\n\n<!-- ===================== FILE: {rel} ===================== -->\n\n{text}")
    OUT.write_text("".join(parts), encoding="utf-8", newline="\n")
    print(f"Wrote {OUT.relative_to(ROOT)} ({OUT.stat().st_size // 1024} KiB) from {len(parts) - 3} files")


if __name__ == "__main__":
    main()
